function renderOrders(){const list=document.querySelector('#order-list'),empty=document.querySelector('#order-empty'),status=document.querySelector('#order-status');list.replaceChildren();let state;try{state=DemoStore.read();status.textContent='';}catch(e){status.textContent=e.message;empty.textContent='저장된 주문을 표시할 수 없습니다.';return;}const filter=document.querySelector('#filter').value,orders=state.orders.filter(o=>filter==='all'||o.side===filter).reverse();empty.textContent=orders.length?'':state.orders.length?'선택한 종류의 주문이 없습니다.':'아직 주문이 없습니다. 매수·매도 연습에서 첫 주문을 해보세요.';status.textContent=`${orders.length}건`;for(const order of orders){const li=document.createElement('li');li.textContent=`${order.name} · ${order.q}주 ${order.side==='buy'?'매수':'매도'}`;const details=document.createElement('small');details.textContent=`${new Date(order.at).toLocaleString('ko-KR')} · ${order.side==='buy'?'결제':'받은'} 금액 ${order.settlement.toLocaleString('ko-KR')}원 · 수수료 ${order.fee.toLocaleString('ko-KR')}원${order.side==='sell'?' · 세금 '+order.tax.toLocaleString('ko-KR')+'원':''}`;li.append(details);list.append(li);}}
document.querySelector('#filter').disabled=true;document.querySelector('#filter').addEventListener('change',renderOrders);AppAccount.ready.then(()=>{document.querySelector('#filter').disabled=false;DemoStore.subscribe(renderOrders);renderOrders();}).catch(e=>{document.querySelector('#order-status').textContent=e.message;});

